Definition cl_cells (c : pcore) (rj : list byte) : list cell :=
  if Z.testbit (pc_f c) 10
  then [C1 (b8 1); CB 7 (skipn 1 (firstn 8 rj)); C8 (wz (pc_len0 c))]
  else [C1 (b8 0); CB 7 (skipn 1 (firstn 8 rj)); C1 (b8 0); CB 7 (skipn 9 rj)].

Definition cl_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P R : Z) (c : pcore) (pad7 pad2 rj : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(R, R + 16)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ rw_cells rsegs m' P (ParserCoreCells c pad7 pad2)
    /\ rw_cells rsegs m' R (cl_cells c rj).

Definition cl_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P R : Z) (c : pcore) (pad7 pad2 rj : list byte),
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c -> 3 <= pc_state c ->
  rw_cells rsegs m R [CB 16 rj] -> (P + 80 <= R \/ R + 16 <= P) ->
  mem_inv rsegs m ->
  evt rsegs (cl_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P R c pad7 pad2 rj m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz R) (wz P) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_CONTENT_LENGTH) fc None m (seg_rom rsegs)).
