(* [comment removed for export] *)
(* [comment removed for export] *)

Definition peof_body_flags (c : pcore) : bool := Z.testbit (pc_f c) 10 || Z.testbit (pc_f c) 11.

(* [comment removed for export] *)
Definition peof_assigns (c : pcore) : bool :=
  (pc_state c <=? 2) || (peof_body_flags c && negb (pc_state c =? 11)).

Definition peof_res (c : pcore) : ecv * pcore :=
  if pc_state c <=? 2 then (EC_http_loc HE_PARTIAL_MESSAGE LOC_PEOF_1, c)
  else if peof_body_flags c then
         (if pc_state c =? 11 then (EC_clear, c) else (EC_http_loc HE_PARTIAL_MESSAGE LOC_PEOF_2, c))
  else (EC_clear, pc_set_state c 11).

(* [comment removed for export] *)
Definition body_W (lo : Z) (sp : word) (P E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (P, P + 80); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

Definition peof_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (g : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (body_W lo sp P E) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' P (ParserCoreCells (snd (peof_res c)) pad7 pad2)
    /\ rw_cells rsegs m' E (ErrCodeCells (fst (peof_res c)))
    /\ HttpCat m' (peof_assigns c || g) /\ XStatics m'.

Definition peof_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P E lo : Z) (c : pcore) (pad7 pad2 ej : list byte) (g : bool),
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c -> pc_state c <> 0 ->
  rw_cells rsegs m E [CB 24 ej] ->
  HttpCat m g -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 80 <= bv_unsigned sp -> 0xb4000 <= lo ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> bv_unsigned sp <= E -> E + 24 <= 2^64 -> (P + 80 <= E \/ E + 24 <= P) ->
  mem_inv rsegs m ->
  evt rsegs (peof_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P E lo c pad7 pad2 g m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz E) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_PUT_EOF) fc None m (seg_rom rsegs)).

(* [comment removed for export] *)
Definition peof_exit_stmt (pc loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0x a1 a2 a3 a4 a5 a6 a7 s0v s1v s1x s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c : pcore) (pad7 pad2 ej j24 : list byte) (g : bool),
  rw_cells rsegs m1 (bv_unsigned sp + -48) [CB 24 j24] ->
  rw_cells rsegs m1 (bv_unsigned sp + -24) [C8 s1v; C8 s0v; C8 ra] ->
  rw_cells rsegs m1 P (ParserCoreCells c pad7 pad2) ->
  rw_cells rsegs m1 E [CB 24 ej] ->
  HttpCat m1 g -> XStatics m1 ->
  stk rsegs m1 lo (bv_unsigned sp + -48) -> lo + 80 <= bv_unsigned sp -> 0xb4000 <= lo ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> bv_unsigned sp <= E -> E + 24 <= 2^64 -> (P + 80 <= E \/ E + 24 <= P) ->
  munch (body_W lo sp P E) m m1 -> wmono rsegs m m1 -> mem_inv rsegs m1 ->
  (pc = 0x394dc -> s1x = wz 2) ->
  evt rsegs (fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (body_W lo sp P E) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' P (ParserCoreCells c pad7 pad2)
    /\ rw_cells rsegs m' E (ErrCodeCells (EC_http_loc HE_PARTIAL_MESSAGE loc))
    /\ HttpCat m' true /\ XStatics m')
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 (wz E) s1x a0x a1 a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom rsegs)).

Local Ltac peof_exit_script :=
  intros rax ra sp gp tp t0 t1 t2 a0x a1 a2 a3 a4 a5 a6 a7 s0v s1v s1x s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
         F fc m m1 P E lo c pad7 pad2 ej j24 g;
  intros FRlo FRhi PC EC HC XS ST LO IMG PLO PHI ELO EHI DPE MU WM MI S1X;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold body_W, G_HTTP_CAT in *; unfold wz in *;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  first [ rewrite (S1X eq_refl) | idtac ]; clear S1X;
  (* [comment removed for export] *)
  steps_to 0x323cc%Z;
  call_assignA_with (bv_unsigned sp + -48) (bv_unsigned sp + -48) 2 lo g j24;
  clear HC XS;
  lazymatch goal with
  | TMP : rw_cells _ _ (bv_unsigned sp + -48) (ErrCodeCells _), HC : HttpCat _ true, XS : XStatics _, ST' : stk _ _ lo _ |- _ =>
    concretize_ec TMP;
