(* [comment removed for export] *)
(* [comment removed for export] *)

Definition PB_RET : Z := 0x3a0f8.

Definition pb_seg1_post (sp : word) (gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (s2 s1 s0 ra : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E n p0 lo : Z) (c : pcore) (pad7 pad2 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR (wz PB_RET) (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 (wz E) (wz P)
                  (wz P) (wz p0) (wz (Z.min (pc_len c) n)) (wz E) (wz P_ON_BODY_IMPL) a5 a6 a7
                  (wz IN) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (wz P_ON_BODY_IMPL) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (E, E + 24)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -32)
    /\ rw_cells rsegs m' (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells rsegs m' P (ParserCoreCells c pad7 pad2)
    /\ rw_cells rsegs m' IN [C8 (wz p0)]
    /\ rw_cells rsegs m' E (ErrCodeCells EC_clear)
    /\ XStatics m'.

Definition pb_seg1_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P IN E n p0 lo : Z) (c : pcore) (pad7 pad2 ej : list byte),
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
  rw_cells rsegs m IN [C8 (wz p0)] ->
  rw_cells rsegs m E [CB 24 ej] ->
  XStatics m ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 32 <= bv_unsigned sp -> 0xb4000 <= lo ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> bv_unsigned sp <= IN -> IN + 8 <= 2^64 -> bv_unsigned sp <= E -> E + 24 <= 2^64 ->
  (P + 80 <= IN \/ IN + 8 <= P) -> (P + 80 <= E \/ E + 24 <= P) -> (IN + 8 <= E \/ E + 24 <= IN) ->
  0 <= n < 2^64 -> 0 <= p0 < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (pb_seg1_post sp gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 s2 s1 s0 ra F fc P IN E n p0 lo c pad7 pad2 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz IN) (wz n) (wz E) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_PARSE_BODY) fc None m (seg_rom rsegs)).

