Definition pb_done (E1 : ecv) (c : pcore) (r : Z) : bool := negb (ec_failed E1) && (pc_len c =? r).

Definition pb_core (E1 : ecv) (c : pcore) (r : Z) : pcore :=
  mkPC (pc_blim_has c) (pc_blim c) (pc_len c - r) (pc_len0 c) (pc_skip c) (pc_hlim c)
       (if pb_done E1 c r then 11 else pc_state c) (pc_f c).

Definition pb_ec (E1 : ecv) (c : pcore) (r : Z) : ecv := if pb_done E1 c r then EC_clear else E1.

Definition pb_seg2_post (rav sp gp tp s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 r : Z) (E1 : ecv) (g : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR rav sp gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc rav) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (P, P + 80); (IN, IN + 8); (E, E + 24)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' P (ParserCoreCells (pb_core E1 c r) pad7 pad2)
    /\ rw_cells rsegs m' IN [C8 (wz (p0 + r))]
    /\ rw_cells rsegs m' E (ErrCodeCells (pb_ec E1 c r))
    /\ HttpCat m' g /\ XStatics m'.

Definition pb_seg2_stmt : Prop :=
  forall rax rav sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 r : Z) (E1 : ecv) (g : bool),
  rw_cells rsegs m (bv_unsigned sp + -32) [C8 s2v; C8 s1v; C8 s0v; C8 rav] ->
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
  rw_cells rsegs m IN [C8 (wz p0)] ->
  rw_cells rsegs m E (ErrCodeCells E1) -> ec_ok E1 ->
  HttpCat m g -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp + -32) -> lo + 32 <= bv_unsigned sp -> 0xb4000 <= lo ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> bv_unsigned sp <= IN -> IN + 8 <= 2^64 -> bv_unsigned sp <= E -> E + 24 <= 2^64 ->
  (P + 80 <= IN \/ IN + 8 <= P) -> (P + 80 <= E \/ E + 24 <= P) -> (IN + 8 <= E \/ E + 24 <= IN) ->
  0 <= r <= pc_len c -> 0 <= p0 -> p0 + r < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (pb_seg2_post rav sp gp tp s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 r E1 g m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 (wz E) (wz P) (wz r) a1 a2 a3 a4 a5 a6 a7
              (wz IN) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 PB_RET) fc None m (seg_rom rsegs)).

